package com.vio.vioaiagent.pokemon.reference;

import com.fasterxml.jackson.databind.node.ObjectNode;
import com.vio.vioaiagent.agent.BuildCheckAnswerEvidence;
import com.vio.vioaiagent.run.*;
import com.vio.vioaiagent.tools.governance.*;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;
import org.springframework.test.web.servlet.setup.MockMvcBuilders;
import java.nio.file.Path;
import java.time.Instant;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;

class LocalBuildCheckServiceTest {
    @TempDir Path directory;
    BuildCheckFixture fixture(){return new BuildCheckFixture(directory);}
    BuildCheckFacts.Request build(BuildCheckFixture f,List<String> moves,String ability){var b=f.request().build();return new BuildCheckFacts.Request(7,new BuildCheckFacts.Build(moves,ability,b.item(),b.nature(),b.level(),b.evs(),b.ivs()),"pokeapi-reference-v1","pokemon-scarlet-violet");}
    @Test void fourMovesBindToOnePokemonSnapshotWithoutAdditionalNetworkOrClaimingJointLegality(){var f=fixture();var r=f.service.check(f.request());assertEquals("REFERENCE_MATCHED",r.status());assertEquals(4,r.moves().size());assertEquals(2,f.networkCalls.get());assertTrue(r.moves().stream().allMatch(m->m.learning().sourceChecksum().equals(r.source().pokemonChecksum())));assertEquals(r,BuildCheckFacts.validate(f.json.valueToTree(r)));}
    @Test void omittedValuesStayMissingRatherThanBecomingConstructorDefaults(){var f=fixture();var q=new BuildCheckFacts.Request(7,new BuildCheckFacts.Build(List.of("surf"),null,null,null,null,null,null),"pokeapi-reference-v1","pokemon-scarlet-violet");var r=f.service.check(q);assertEquals("INCOMPLETE",r.status());assertTrue(r.missingFields().containsAll(List.of("ability","nature","level","evs.hp","ivs.hp","moves.fourSlots")));assertNull(r.request().build().level());assertNull(r.request().build().nature());}
    @Test void absenceAndAbilityMismatchAreNotAnUnlearnabilityOrLegalityVerdict(){var f=fixture();var r=f.service.check(build(f,List.of("surf","ice-beam","protect","fire-blast"),"snow-cloak"));assertEquals("REFERENCE_MISMATCH",r.status());assertEquals("NOT_IN_SNAPSHOT",r.abilityStatus());assertEquals("NOT_RECORDED",r.moves().get(3).status());var e=new BuildCheckAnswerEvidence();e.observe(f.json.valueToTree(r).toString(),"{\"request\":"+f.json.valueToTree(r.request())+"}");assertTrue(e.summary("").contains("不能据此断言无法学习"));assertFalse(e.summary("").contains("合法性通过"));}
    @Test void oneFailedLearningReadPreservesOtherRowsButCannotReturnMatched(){var f=fixture();var reads=spy(f.learning);doThrow(new IllegalStateException("private-upstream-detail")).when(reads).read(7,"ice-beam","pokeapi-reference-v1","pokemon-scarlet-violet");var r=new LocalBuildCheckService(f.json,f.repository,reads,f.client).check(f.request());assertEquals("REFERENCE_UNAVAILABLE",r.status());assertEquals(3,r.moves().stream().filter(m->m.status().equals("RECORDED")).count());assertFalse(f.json.valueToTree(r).toString().contains("private-upstream-detail"));}
    @Test void learningRowsFromADifferentSnapshotNeverBecomeVerifiedMembership(){var f=fixture();var reads=spy(f.learning);var changed=PokemonLearnsetFacts.create(7,"squirtle","surf",List.of(new PokemonLearnsetFacts.Entry("machine",0,null)),new PokeApiClient.Snapshot("other",PokeApiClient.digest("other"),Instant.now(),"https://pokeapi.co/api/v2/pokemon/7/"));doReturn(changed).when(reads).read(7,"surf","pokeapi-reference-v1","pokemon-scarlet-violet");var r=new LocalBuildCheckService(f.json,f.repository,reads,f.client).check(f.request());assertEquals("REFERENCE_UNAVAILABLE",r.status());assertNull(r.moves().get(3).learning());}
    @Test void normalizedAliasDuplicatesAndOutOfRangeStatsFailBeforeAnyReferenceRead(){var f=fixture();var r=f.service.check(build(f,List.of("Ice Beam","ice  beam","protect","surf"),"torrent"));assertEquals("INVALID_INPUT",r.status());var b=f.request().build();var q=new BuildCheckFacts.Request(7,new BuildCheckFacts.Build(b.moves(),b.ability(),b.item(),b.nature(),50,new BuildCheckFacts.Stats(252,252,252,0,0,0),b.ivs()),"pokeapi-reference-v1","pokemon-scarlet-violet");assertEquals("INVALID_INPUT",f.service.check(q).status());assertEquals(0,f.networkCalls.get());}
    @Test void titleCaseAndSpacesNormalizeForMatchingWithoutChangingTheInput(){var f=fixture();var q=build(f,List.of("Water Pulse","Ice Beam","Protect","Surf"),"Torrent");var r=f.service.check(q);assertEquals("REFERENCE_MATCHED",r.status());assertEquals("Water Pulse",r.request().build().moves().get(0));assertEquals("water-pulse",r.moves().get(0).normalized());}
    @Test void rawJsonTypeCoercionAndUnknownFieldsAreRejected(){var f=fixture();var node=(ObjectNode)f.json.valueToTree(f.request());((ObjectNode)node.path("build")).put("level","50");assertThrows(IllegalArgumentException.class,()->BuildCheckFacts.parseRequest(node));var extra=(ObjectNode)f.json.valueToTree(f.request());((ObjectNode)extra.path("build")).put("isLegal",true);assertThrows(IllegalArgumentException.class,()->BuildCheckFacts.parseRequest(extra));assertEquals(0,f.networkCalls.get());}
    @Test void changedOutcomeAndDifferentRequestCannotAcquireValidEvidence(){var f=fixture();var r=f.service.check(build(f,List.of("surf"),"torrent"));var node=(ObjectNode)f.json.valueToTree(r);node.put("status","REFERENCE_MATCHED");assertThrows(IllegalArgumentException.class,()->BuildCheckFacts.validate(node));String args="{\"request\":"+f.json.valueToTree(f.request())+"}";assertThrows(IllegalArgumentException.class,()->BuildCheckAnswerEvidence.bound(f.json.valueToTree(r).toString(),args));}
    @Test void httpChecksTheSuppliedDraftAndRejectsUnknownVersionsAndStringNumbers() throws Exception{var f=fixture();var mvc=MockMvcBuilders.standaloneSetup(new PokemonBuildCheckController(f.service)).build();mvc.perform(post("/pokemon/reference/build-check").contentType("application/json").content(f.json.writeValueAsString(f.request()))).andExpect(status().isOk()).andExpect(jsonPath("$.status").value("REFERENCE_MATCHED"));var q=(ObjectNode)f.json.valueToTree(f.request());q.put("gameReleaseId","pokemon-sword-shield");mvc.perform(post("/pokemon/reference/build-check").contentType("application/json").content(q.toString())).andExpect(status().isBadRequest());((ObjectNode)q.path("build")).put("level","50");mvc.perform(post("/pokemon/reference/build-check").contentType("application/json").content(q.toString())).andExpect(status().isBadRequest());}
    @Test void cancellationStopsBeforeAnyNetworkRead(){var f=fixture();Thread.currentThread().interrupt();try{assertThrows(IllegalStateException.class,()->f.service.check(f.request()));assertEquals(0,f.networkCalls.get());}finally{Thread.interrupted();}}
    @Test void toolRequiresBothRunVersionsAndOwnershipBeforeChecking(){var f=fixture();var runs=new InMemoryRunRepository();runs.save(AgentRun.create("run-build-check","session","conversation","alice","test","pokemon-scarlet-violet","casual-singles","casual-v1","zh-CN",null,"pokeapi-reference-v1",null,null,"v1","trace",null,null));var tool=new PokemonBuildCheckController.Tools(f.service,new RunToolScope(runs));ToolExecutionContextHolder.set(new ToolExecutionContext("alice","run-build-check",Set.of("trainer"),"trace",null,null));try{assertEquals("REFERENCE_MATCHED",tool.checkPokemonBuild(f.request()).status());ToolExecutionContextHolder.set(new ToolExecutionContext("bob","run-build-check",Set.of("trainer"),"trace",null,null));assertThrows(IllegalStateException.class,()->tool.checkPokemonBuild(f.request()));}finally{ToolExecutionContextHolder.clear();}}
}
